      "ur": "یقیناً تم سب کا معبود ایک ہی ہے.[1]",
      "en": "Indeed, your God is One,",
      "footnotesUr": "[1] صَافَّاتٌ، زَاجِرَاتٌ، تَالِياتٌ فرشتوں کی صفات ہیں۔ آسمانوں پر اللہ کی عبادت کے لئے صف باندھنے والے، یا اللہ کے حکم کے انتظار میں صف بستہ، وعظ ونصیحت کے ذریعے سے لوگوں کوڈانٹنے والے یا بادلوں کو، جہاں اللہ کا حکم ہو، وہاں ہانک کر لےجانے والے۔ اللہ کا ذکر یا قرآن کی تلاوت کرنے والے۔ ان فرشتوں کی قسم کھا کر اللہ تعالیٰ نے مضمون یہ بیان فرمایا کہ تمام انسانوں کا معبود ایک ہی ہے۔ متعدد نہیں، جیسا کہ مشرکین بنائےہوئے ہیں۔ عرف عام میں قسم تاکید اور شک دور کرنے کے لئےکھائی جاتی ہے، اللہ تعالیٰ نے یہاں قسم اسی شک کو دور کرنے کے لئےکھائی ہے جو مشرکین اس کی وحدانیت والوہیت کے بارے میں پھیلاتے ہیں۔ علاوہ ازیں ہر چیز اللہ کی مخلوق اور مملوک ہے، اس لئے وہ جس چیز کو بھی گواہ بنا کر اس کی قسم کھائے، اس کے لئے جائز ہے۔ لیکن انسانوں کےلئے اللہ کے سوا کسی اور کی قسم کھانا بالکل ناجائز اور حرام ہے، کیونکہ قسم میں، جس کی قسم کھائی جاتی ہے، اسے گواہ بنانا مقصود ہوتا ہے۔ اور گواہ اللہ کے سوا کوئی نہیں بن سکتا، کہ عالم الغیب صرف وہی ہے، اس کےسوا کوئی عالم الغیب نہیں۔",
