      "footnotesUr": "[1] أَهْلٌ سے مراد، حضرت نوح (عليه السلام) پر ایمان لانے والے ہیں، جن میں ان کے گھر کے افراد بھی ہیں جو مومن تھے۔ بعض مفسرین نے ان کی کل تعداد 8۔ بتلائی ہے۔ اس میں آپ کی بیوی اور ایک لڑکا شامل نہیں، جو مومن نہیں تھے، وہ بھی طوفان میں غرق ہو گئے۔ کرب عظیم (زبردست مصیبت) سے مراد وہی سیلاب عظیم ہے جس میں یہ قوم غرق ہوئی۔",
