      "en": "You have fulfilled the vision.\" Indeed, We thus reward the doers of good.",
      "footnotesUr": "[1] یعنی دل کےپورےارادے سے بچے کو ذبح کرنے کے لئے زمین پر لٹا دینے سے ہی تو نے اپنا خواب سچا کر دکھایا ہے، کیونکہ اس سے واضح ہو گیا کہ اللہ کے حکم کے مقابلے میں تجھے کوئی چیز بھی عزیز تر نہیں ہے، حتیٰ کہ اکلوتا بیٹا بھی۔",
